command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FALSCHE FÄHRTE (RONDRA)
//
// - mehrere Targets ohne Reichweitenprüfung
// - Zielkategorie: Erwachte
// - gültige Ziele = Erfolg und erhalten den Effekt
// - ungültige Ziele = Misserfolg
// - gemischte Target-Auswahl wird verarbeitet
// - gespeicherte Ziele, kein erneutes Target
// - roter GM-Button im verborgenen Bereich
// - direkte Effektanlage über Block 5
// - eine gemeinsame Karte
// - Wirkungsende über Block 6
// - alte Effekte nur desselben Wirkenden ersetzen
// - kein automatischer „Effekt konnte nicht angelegt werden“-Zusatz
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.Effekt?.CheckTarget ||
        !globalThis.DSK?.EffektEnde?.Register || !globalThis.DSK?.QS?.Ermitteln ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton || !globalThis.DSK?.GabenUI?.Details;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.Effekt?.CheckTarget ||
        !DSK_FW?.EffektEnde?.Register || !DSK_FW?.QS?.Ermitteln ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton || !DSK_FW?.GabenUI?.Details
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Falsche Fährte", vollerName = "Falsche Fährte (Rondra)", ahne = "Rondra";
    const flagKey = "pendingFalscheFaehrteRondra", endeKey = "rondraFalscheFaehrte";
    const endeText = "Die illusionäre Fährte verblasst, und es werden wieder die echten Spuren hinterlassen.";

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const dokument = await fromUuid(uuid);
            return dokument?.documentName === "Token" ? dokument.actor : dokument || null;
        } catch (error) {
            console.warn("Falsche Fährte: Actor konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    const findeFaehrtenEffekte = (actor, casterUuid) => (actor?.effects || []).filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "isFalscheFaehrte") === true &&
        effect.getFlag("dsk", "casterUuid") === casterUuid
    );

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
            await actor.unsetFlag("world", "letzteGabenQS");
        }
    };

    // +++ 4 - GABENSPEZIFISCHE KARTE ++++++++++++++++++++++++++
    // Absichtlich eigener Ziel-/Misserfolgsbereich:
    // kein automatischer Zusatz „Effekt konnte nicht angelegt werden“.

    const baueKarte = ({
        beschreibung = "", casterName = "", erfolge = [], misserfolge = [],
        dauerText = "", gmLink = "", gmBereich = false,
        angewendet = false, erfolgreich = false
    } = {}) => {
        const statusHtml = angewendet
            ? `<p style="text-align:center;color:${erfolgreich ? "#18940F" : "#B30000"};font-weight:bold;">${erfolgreich ? "Erfolg" : "Misserfolg"}</p>`
            : "";

        const erfolgHtml = erfolge.length
            ? erfolge.map(ziel =>
                `<p style="margin:8px 0 4px;text-align:left;"><b>Veränderte Fährte:</b></p>` +
                DSK_FW.UI.List([ziel.name])
            ).join("")
            : "";

        const misserfolgHtml = misserfolge.length
            ? `<hr><p style="text-align:center;color:#B30000;font-weight:bold;">Misserfolg</p>` +
              DSK_FW.UI.List(misserfolge.map(eintrag =>
                  typeof eintrag === "string"
                      ? eintrag
                      : `${eintrag?.name || "Unbekannt"}${eintrag?.grund ? ` – ${eintrag.grund}` : ""}`
              ))
            : "";

        const gmHtml = gmBereich && !angewendet
            ? `<section class="secret">
                <hr>
                <div style="text-align:center;">
                    <p style="margin:0 0 6px;color:#76301b;font-weight:bold;">Effektanwendung durch die Spielleitung</p>
                    <p style="margin:0 0 6px;font-size:.82em;color:#555;">Es ist keine erneute Target-Auswahl nötig.</p>
                    <div style="display:flex;justify-content:center;margin-top:6px;">${gmLink}</div>
                </div>
            </section>`
            : "";

        return `
            ${DSK_FW.UI.Header(vollerName, DSK_FW.Symbol(ahne))}
            <div class="dskbox2" style="margin-top:10px;">
                ${beschreibung
                    ? `${DSK_FW.GabenUI.Details({
                        titel: "Gabenwirkung Information",
                        inhalt: beschreibung,
                        zentriert: true
                    })}<hr>`
                    : ""}
                ${statusHtml}
                <p style="margin:0 0 4px;text-align:left;"><b>Wirkender:</b></p>
                ${DSK_FW.UI.List([casterName])}
                ${erfolgHtml}
                ${misserfolgHtml}
                <hr>
                <p style="text-align:center;margin-bottom:0;"><b>Wirkungsdauer:</b> ${dauerText}</p>
                ${gmHtml}
            </div>`;
    };

    // +++ 5 - EFFEKT DIREKT ÜBER BLOCK 5 ++++++++++++++++++++++

    const wendeFalscheFaehrteAn = async ({
        casterActor, targetActor, targetName, qs, dauerMinuten
    }) => {
        if (!casterActor || !targetActor) return false;
        if (!DSK_FW.Effekt.CheckTarget(targetActor, "erwachte")) return false;

        const alteEffekte = findeFaehrtenEffekte(targetActor, casterActor.uuid);

        if (alteEffekte.length) {
            await targetActor.deleteEmbeddedDocuments("ActiveEffect", alteEffekte.map(effect => effect.id));
        }

        const effektBeschreibung =
            `<b>${targetName}</b> hinterlässt statt der eigenen Spuren Spuren eines anderen Tieres ähnlicher Größe, ` +
            `beispielsweise eines kleinen Hundes, einer großen Ratte oder eines Hasen.` +
            `<br><br><b>Zielkategorie:</b> Erwachte` +
            `<br><b>Gabe gewirkt von:</b> ${DSK_FW.ResolveTokenName(casterActor)}` +
            `<br><b>Wirkungsdauer:</b> ${dauerMinuten} Minuten`;

        const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
            name: vollerName, ahne, beschreibung: effektBeschreibung,
            gabeZiel: "erwachte", qs, ziel: targetActor,
            duration: { seconds: dauerMinuten * 60, startTime: game.time.worldTime },
            showIcon: 1,
            flags: { dsk: {
                isFalscheFaehrte: true, casterUuid: casterActor.uuid, qs,
                wirkungsende: {
                    sfName: endeKey, basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }}
        });

        if (!erzeugterEffekt) return false;

        const endeDaten = erzeugterEffekt.getFlag("dsk", "wirkungsende");

        return (
            (erzeugterEffekt.name || erzeugterEffekt.label || "") === vollerName &&
            erzeugterEffekt.getFlag("dsk", "isFalscheFaehrte") === true &&
            erzeugterEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
            Number(erzeugterEffekt.getFlag("dsk", "qs")) === qs &&
            endeDaten?.sfName === endeKey &&
            endeDaten?.basisEffektName === vollerName
        );
    };

    // +++ 6 - GM-ANFRAGE VERARBEITEN ++++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !game.user.isGM) return false;

        if (daten.casterUuid && daten.casterUuid !== casterActor.uuid) {
            ui.notifications.warn("Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum wirkenden Akteur.");
            return false;
        }

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const dauerMinuten = qs * 10, dauerText = `${dauerMinuten} Minuten (${qs} QS × 10 Min)`;
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const erfolge = [], misserfolge = foundry.utils.deepClone(daten.misserfolge || []);

        for (const ziel of daten.ziele || []) {
            const targetActor = await ladeActor(ziel.actorUuid);
            const targetName = ziel.name || targetActor?.name || "Unbekanntes Ziel";

            if (!targetActor) {
                misserfolge.push(`${targetName} – Ziel nicht gefunden`);
                continue;
            }

            if (!DSK_FW.Effekt.CheckTarget(targetActor, "erwachte")) {
                misserfolge.push(`${targetName} – Kein Erwachter`);
                continue;
            }

            try {
                const effektErfolgreich = await wendeFalscheFaehrteAn({
                    casterActor, targetActor, targetName, qs, dauerMinuten
                });

                if (effektErfolgreich) erfolge.push({ name: targetName });
                else misserfolge.push(targetName);

            } catch (error) {
                console.error("Falsche Fährte: Effektanlage fehlgeschlagen.", { ziel, error });
                misserfolge.push(targetName);
            }
        }

        const erfolgreich = erfolge.length > 0;
        const message = game.messages.get(daten.messageId);

        if (message) {
            await message.update({
                content: baueKarte({
                    beschreibung: daten.beschreibung || "", casterName,
                    erfolge, misserfolge, dauerText,
                    gmBereich: false, angewendet: true, erfolgreich
                }),
                "flags.dsk.angewendet": true
            });
        }

        if (erfolgreich) {
            ui.notifications.info(`Luna sagt 🌙: Falsche Fährte wurde auf ${erfolge.length} Ziel(e) angewendet.`);
        } else {
            ui.notifications.error("Luna sagt 🌙: Falsche Fährte konnte auf kein Ziel angewendet werden!");
        }

        return true;
    };

    // +++ 7 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }

            return;
        }
    }

    // +++ 8 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Falsche Fährte Probe", "Falsche Fährte"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    const dauerMinuten = qs * 10, dauerText = `${dauerMinuten} Minuten (${qs} QS × 10 Min)`;
    const beschreibung =
        `Die ausgewählten Erwachten hinterlassen statt ihrer eigenen Spuren Spuren eines anderen Tieres ähnlicher Größe, ` +
        `beispielsweise eines kleinen Hundes, einer großen Ratte oder eines Hasen.` +
        `<br><br><b>Zielkategorie:</b> Erwachte`;

    // +++ 9 - TARGETS PRÜFEN +++++++++++++++++++++++++++++++++++

    const targets = Array.from(game.user.targets || []);

    if (!targets.length) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle mindestens ein Ziel per Target aus!");
    }

    const gueltigeZiele = [], misserfolge = [];

    for (const targetToken of targets) {
        const targetActor = targetToken?.actor;
        const targetName = targetToken?.name || targetActor?.name || "Unbekanntes Target";

        if (!targetActor) {
            misserfolge.push(`${targetName} – Kein gültiger Akteur`);
            continue;
        }

        if (!DSK_FW.Effekt.CheckTarget(targetActor, "erwachte")) {
            misserfolge.push(`${targetName} – Kein Erwachter`);
            continue;
        }

        gueltigeZiele.push({
            actorUuid: targetActor.uuid, tokenId: targetToken.id,
            tokenUuid: targetToken.document?.uuid || targetToken.uuid || null,
            name: targetName
        });
    }

    // +++ 10 - KEIN GÜLTIGES ZIEL +++++++++++++++++++++++++++++

    if (!gueltigeZiele.length) {
        await ChatMessage.create({
            speaker: { alias: "System" },
            content: baueKarte({
                beschreibung, casterName, erfolge: [], misserfolge, dauerText,
                gmBereich: false, angewendet: true, erfolgreich: false
            })
        });

        await raeumeQSAuf(casterActor);

        ui.notifications.warn(
            "Luna sagt 🌙: Kontrolliere deine Target-Auswahl. Wirke die Gabe erneut, wenn es der GM erlaubt; ansonsten ist dies ein Fehlschlag."
        );
        return;
    }

    // +++ 11 - GEMEINSAME KARTE + ROTER GM-BUTTON +++++++++++++

    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Falsche Fährte anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await ChatMessage.create({
        speaker: { alias: "System" },
        flags: { dsk: {
            gabenAnfrage: true, gabenName: vollerName,
            angewendet: false, anfragenderUserId: game.user.id
        }},
        content: baueKarte({
            beschreibung, casterName,
            erfolge: gueltigeZiele.map(ziel => ({ name: ziel.name })),
            misserfolge, dauerText, gmLink,
            gmBereich: !game.user.isGM, angewendet: false, erfolgreich: false
        })
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
    }

    // +++ 12 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName, qs, dauerMinuten,
        ziele: gueltigeZiele, misserfolge, beschreibung,
        sceneId: canvas.scene?.id || null, requestedByUserId: game.user.id,
        messageId: nachricht.id, macroUuid
    };

    // +++ 13 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);

    // +++ 14 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);
    ui.notifications.info("Luna sagt 🌙: Die Anwendung von Falsche Fährte wurde bei der Spielleitung beantragt.");

}).call(this);
